IF NOT EXISTS (SELECT 1 FROM Control_Library)
BEGIN
    INSERT INTO Control_Library (ControlCode, ITOT, Domain, ControlName, ControlDescription, SampleEvidence, CreatedBy) VALUES
        ('CII-CID-001', 'OT', 'Asset Management', 'Asset Inventories', 'Mechanisms exist to perform inventories of Technology Assets, Applications, Services and/or Data (TAASD) that:
